using End2EndThermalImg
using Distributed
using Logging

# One-off backfill: adds PSFs_initial.png to a run folder whose checkpoint report was already
# generated by scripts/checkpoint_report.jl before save_checkpoint_report (src/optimize.jl) started
# saving it -- see that function's own comment for why PSFs_initial.png isn't among a timed-out/
# cancelled run's existing artifacts in the first place. Everything else in the run folder (geoms_
# comparison_checkpoint.png, PSFs_checkpoint.png, reconstruction_checkpoint*.png) is left untouched.
# Run via: E2E_RUN_FOLDER=optdata/opt_<datetime> sbatch cluster_scripts/run_add_psfs_initial.sh
global_logger(ConsoleLogger(stdout))

nw = End2EndThermalImg.setup_cluster_workers()
println("nworkers = ", nworkers(), "  workers = ", workers())

run_folder = get(ENV, "E2E_RUN_FOLDER", "optdata/opt_2026-11-13T13:07:16.666")
isdir(run_folder) || error("E2E_RUN_FOLDER does not exist: $run_folder")

println("\n--- loading checkpoint from ", run_folder, " ---")
state = End2EndThermalImg.load_checkpoint_state(run_folder)
php, imghp, PSF_scale = state.php, state.imghp, state.PSF_scale
geoms_init_flat, geoms_opt_flat = state.geoms_init_flat, state.geoms_opt_flat

for (name, value) in ((:php, php), (:imghp, imghp))
    End2EndThermalImg.broadcast_value(name, value)
end

println("\n--- setup ---")
@time driver_plans_n2f, driver_plans_PSF = End2EndThermalImg.setup_fft_plans_distributed!(php, imghp)
@time freqs = End2EndThermalImg.get_freq_chebpoints(php)
@time n2f_kernels = End2EndThermalImg.compute_and_broadcast(:n2f_kernels, End2EndThermalImg.get_n2f_kernels, freqs, driver_plans_n2f, php, imghp)

@everywhere begin
    surrogates = End2EndThermalImg.load_surrogate_models(php)
    PSF_zcoords = End2EndThermalImg.get_PSF_zcoords(imghp)
end

@time End2EndThermalImg.assign_shard_indices!()
@time End2EndThermalImg.init_resident_incidents!(freqs, PSF_zcoords, php)

println("\n--- gathering PSFs ---")
geoms_init = End2EndThermalImg.unflatten_square_matrix(geoms_init_flat)
geoms_opt = End2EndThermalImg.unflatten_square_matrix(geoms_opt_flat)

# vmin/vmax shared with geoms_opt's PSFs, matching the scale PSFs_checkpoint.png (already saved)
# was plotted with -- so the two remain visually comparable.
PSFs_initial = End2EndThermalImg.gather_PSFs_distributed(geoms_init, freqs, php, imghp, PSF_scale, driver_plans_PSF, PSF_zcoords)
PSFs_checkpoint = End2EndThermalImg.gather_PSFs_distributed(geoms_opt, freqs, php, imghp, PSF_scale, driver_plans_PSF, PSF_zcoords)

PSF_vmin = minimum(minimum(minimum.(PSFs)) for PSFs in (PSFs_initial, PSFs_checkpoint))
PSF_vmax = maximum(maximum(maximum.(PSFs)) for PSFs in (PSFs_initial, PSFs_checkpoint))
End2EndThermalImg.plot_PSFs_grid(PSFs_initial, PSF_zcoords, freqs; vmin = PSF_vmin, vmax = PSF_vmax,
    extra_title = "initial", savefile = "$(run_folder)/PSFs_initial.png")

println("\n=== Done ===")
println("wrote ", joinpath(run_folder, "PSFs_initial.png"))
